    if k == 'abomination_barred':
        return [E_('house_abomination_barred', 'israel', value={'the_word': 'and you shall not bring an abomination into your house, and become devoted like it (7:26)', 'the_exam': ["the renting for a residence barred everywhere — the house still a Jew's by name (Mishnah Avodah Zarah 1:8-9; 15a:7, 21a:2)", 'the wall against the idol\'s house withdrawn four cubits — its space a bathroom or thorns (Mishnah 3:6; 47b:4-8)', "a house bowed to forbidden — built for it or bowed to, either way (Rav, 47b:10-11)", "the idol's stones, wood and dust impure as a creeping animal (7:26's verb; Leviticus 11:43) or a menstruant by carrying (R. Akiva; Shabbat 82b; Tosefta Zavim 5:6)", 'no consecration to an idol by word (44b:14)'], 'devoted_like_it': "whatever you generate from it is like it — the exchange forbidden, the exchange's exchange disputed (Avodah Zarah 54b; Kiddushin 58a; Chullin 140a; Temurah 30b); the Asherah's wood flogged under 7:26 (Makkot 22a; Pesachim 48a)", 'coveting': "7:25 'you shall not covet the silver and gold on them' — the tenth word's verb turned to the idols (the readback row); coveting_barred UNMOVED (CQ7)", 'day': "the counter's (40, 11, 1), no marker"}, law="F6 [INK 7:25-26 'the graven images of their gods you shall burn with fire; you shall not covet the silver and gold on them … and you shall not bring an abomination into your house, and become devoted like it; you shall utterly detest it and utterly abhor it, for it is devoted' — THE CODE'S HOLE compiled at 5b from the ink with Mishnah Avodah Zarah 1:8-9, 3:6 and Avodah Zarah 47b, 54b, Makkot 22a: a BLOCK on Israel at the chapter's third line (CQ7); the coveting the tenth word's, no second write]")]
    if k == 'seven_nations_case':
        fn = {'nations': the_seven_nations, 'holy': the_holy_people, 'faithful': the_faithful_god, 'hear': because_you_hear, 'fear': do_not_fear, 'images': the_images_and_the_devoted}[event['cell']]
        v, e, _ = fn({'ask': event['ask']}, DATA); L = '%s [%s]' % ({'nations': 'F1', 'holy': 'F2', 'faithful': 'F3', 'hear': 'F4', 'fear': 'F5', 'images': 'F6'}[event['cell']], event['ask']); s_ = event['person']
