        w.submit({'kind': 'seven_nations_case', 'subject': 'the-renter-of-a-house-in-the-land', 'person': 'the-renter-of-a-house-in-the-land', 'cell': 'nations', 'ask': 'no_favor', 'case_source': "Mishnah Avodah Zarah 1:8; Avodah Zarah 20a:1-4 — the exam's row no_favor"})
        w.submit({'kind': 'seven_nations_case', 'subject': 'the-praiser-who-thanks-the-creator', 'person': 'the-praiser-who-thanks-the-creator', 'cell': 'nations', 'ask': 'praise_of_the_creator', 'case_source': "Avodah Zarah 20a:10-11, 20b:3 — the exam's row praise_of_the_creator"})
        w.submit({'kind': 'seven_nations_case', 'subject': 'the-gentile-womans-betrothed', 'person': 'the-gentile-womans-betrothed', 'cell': 'nations', 'ask': 'no_marriage', 'case_source': "Kiddushin 68b:2; Avodah Zarah 36b:5 — the exam's row no_marriage"})
