        w.submit({'kind': 'seven_nations_case', 'subject': 'the-one-without-another-way', 'person': 'the-one-without-another-way', 'cell': 'nations', 'ask': 'no_other_way', 'case_source': "Avodah Zarah 48b:7-10 — the exam's row no_other_way"})
        w.submit({'kind': 'seven_nations_case', 'subject': 'the-asherahs-wood-burner', 'person': 'the-asherahs-wood-burner', 'cell': 'nations', 'ask': 'the_asherah_wood', 'case_source': "Makkot 22a:2-3; Pesachim 48a:6; Mishnah Avodah Zarah 3:9 — the exam's row the_asherah_wood"})
        w.submit({'kind': 'seven_nations_case', 'subject': 'the-canaanite-outside-the-land', 'person': 'the-canaanite-outside-the-land', 'cell': 'nations', 'ask': 'the_bans_condition', 'case_source': "Sotah 35b:10-13, 36a:1 — the exam's row the_bans_condition"})
        w.submit({'kind': 'seven_nations_case', 'subject': 'the-robber-of-a-gentile', 'person': 'the-robber-of-a-gentile', 'cell': 'hear', 'ask': 'consume_no_pity', 'case_source': "Bava Kamma 113b:7 — the exam's row consume_no_pity"})
