        w.submit({'kind': 'seven_nations_case', 'subject': 'the-finder-of-the-money-at-the-idols-head', 'person': 'the-finder-of-the-money-at-the-idols-head', 'cell': 'images', 'ask': 'the_money_at_the_head', 'case_source': "Mishnah Avodah Zarah 4:2; Avodah Zarah 51b:13-14 — the exam's row the_money_at_the_head"})
