def narrative():
    """THE DEUTERONOMY WALK 5b (2026-09-18): the chapter's own acts AS HISTORY — the three lines on the counter's own day (40, 11, 1), NO marker (the
    speech continuing from chapter 6's own-day lines) — on a world with this runner's daemon: 7 writes (the ban's debit, three blocks, the blessings'
    entry, the pity's block, the abomination's block), no timer, ONE entity (Israel), the counter at (11, 1), no close, no row, no dated line. Recorded
    by the sequential run's recorder and stitched onto the tape (page_order after the last Deuteronomy 6 line). Not a graded cell: the tuple below is a
    tripwire typed from the design."""
    with contextlib.redirect_stdout(io.StringIO()):
        w = WE.World(era='Deut 7:1-26 on the tape — the seven nations devoted, the hearing blessed and the abomination barred, the counter\'s own day (the exodus epoch)', epoch='exodus')
        w.laws = [law_seven_nations]
        w.advance(w.clock.day_in('exodus', 40, 11, 1))
        # THE DAEMON GATE READS LITERAL SUBMITS ONLY — the three lines typed out; no marker; no field named `until`, `days` or `due`
        w.submit({'kind': 'nations_devoted', 'subject': 'israel', 'nations': ['the Hittite', 'the Girgashite', 'the Amorite', 'the Canaanite', 'the Perizzite', 'the Hivite', 'the Jebusite'], 'objects': ['altars', 'pillars', 'Asherim', 'graven images'], 'case_source': LINES[0][0]})
        w.submit({'kind': 'hearing_blessed', 'subject': 'israel', 'condition': 'because you hear these judgments and keep and do them (7:12)', 'blessings': ['love, blessing, increase (7:13)', 'no barren (7:14)', 'sickness removed (7:15)'], 'case_source': LINES[1][0]})
        w.submit({'kind': 'abomination_barred', 'subject': 'israel', 'objects': ['the graven images burned', 'the silver and gold not coveted'], 'devoted': 'the abomination not into your house, lest you become devoted like it (7:26)', 'case_source': LINES[2][0]})
    writes = len([l for l in w.log if l[0] == 'WRITE'])
    closes = len([e for ent in w.entities.values() for e in ent.ledger if e.get('closed_by')])
    rows = len([l for l in w.log if l[0] == 'ROW'])
    dated = len([l for l in w.log if l[0] == 'EVENT' and l[2].get('dated') is not None])
    return (writes, len([l for l in w.log if l[0] == 'TIMER-SET']), len(w.entities), w.clock.eras['exodus'].date(w.clock.day)[1:], closes, rows, len(w.tables['population']), dated), w


NARRATIVE, _WN = narrative()
